css:
@page { size: 11in 8.5in; margin: 0; }
* { box-sizing: border-box; margin: 0; padding: 0; }
body { font-family: 'Inter', Arial, sans-serif; color: #1a1a1a; -webkit-print-color-adjust: exact; }

.cert-page {
    position: relative;
    width: 11in;
    height: 8.5in;
    overflow: hidden;
    background: #ffffff;
}
.cert-frame {
    position: absolute;
    top: 0; left: 0;
    width: 11in;
    height: 8.5in;
    z-index: 0;
}

.cert-logos {
    position: absolute;
    top: 0.55in;
    left: 0;
    width: 11in;
    text-align: center;
    z-index: 2;
}
.cert-logos img {
    display: inline-block;
    vertical-align: middle;
}
.cert-logo-ppt { height: 0.95in; margin-right: 0.4in; }
.cert-logo-ppt4ed { height: 0.65in; }
.cert-logo-ppt4ed-alone { height: 0.85in; }

.cert-title {
    position: absolute;
    top: 2in;
    left: 0;
    width: 11in;
    text-align: center;
    font-family: 'Playfair Display', 'Georgia', serif;
    font-size: 42pt;
    font-weight: 400;
    line-height: 1;
    z-index: 2;
}

.cert-subtitle {
    position: absolute;
    top: 3in;
    left: 1.5in;
    width: 8in;
    text-align: center;
    font-size: 11pt;
    font-weight: 400;
    letter-spacing: 0.08em;
    line-height: 1.6;
    z-index: 2;
}

.cert-recipient-name {
    position: absolute;
    top: 3.85in;
    left: 0;
    width: 11in;
    text-align: center;
    font-size: 18pt;
    font-weight: 500;
    letter-spacing: 0.02em;
    z-index: 2;
}

.cert-license {
    position: absolute;
    top: 4.35in;
    left: 0;
    width: 11in;
    text-align: center;
    font-size: 10pt;
    color: #555;
    letter-spacing: 0.04em;
    z-index: 2;
}

.cert-preamble {
    position: absolute;
    top: 4.75in;
    left: 0;
    width: 11in;
    text-align: center;
    font-size: 12pt;
    z-index: 2;
}

.cert-course-title {
    position: absolute;
    top: 5.15in;
    left: 1in;
    width: 9in;
    text-align: center;
    font-size: 24pt;
    font-weight: 700;
    line-height: 1.25;
    z-index: 2;
}

.cert-signatures {
    position: absolute;
    top: 6.3in;
    left: 0;
    width: 11in;
    text-align: center;
    z-index: 2;
}
.cert-sig-block {
    display: inline-block;
    vertical-align: top;
    width: 3in;
    margin: 0 0.4in;
    text-align: center;
}
.cert-sig {
    display: block;
    height: 0.6in;
    max-width: 100%;
    object-fit: contain;
    margin: 0 auto 2pt;
}
.cert-sig-placeholder { height: 0.6in; }
.cert-sig-line {
    border-top: 1px solid #222;
    position: relative;
    margin: 2pt 0;
}
.cert-sig-line::before, .cert-sig-line::after {
    content: '';
    position: absolute;
    top: -4pt;
    width: 1px;
    height: 8pt;
    background: #222;
}
.cert-sig-line::before { left: 0; }
.cert-sig-line::after { right: 0; }
.cert-sig-name {
    font-size: 11pt;
    font-weight: 500;
    letter-spacing: 0.04em;
    padding-top: 4pt;
}

.cert-footer {
    position: absolute;
    bottom: 0.75in;
    left: 1in;
    width: 9in;
    z-index: 2;
}
.cert-footer::after { content: ''; display: block; clear: both; }
.cert-footer-left {
    float: left;
    text-align: left;
    font-size: 10pt;
    letter-spacing: 0.06em;
    line-height: 1.6;
}
.cert-footer-right {
    float: right;
    text-align: right;
    font-size: 10pt;
    letter-spacing: 0.06em;
    line-height: 1.6;
}
.cert-footer-heading { font-weight: 500; }

html:
{%- set member = frappe.db.get_value("User", doc.member, ["full_name"], as_dict=True) -%}
{%- set course = frappe.db.get_value("LMS Course", doc.course, ["title", "name"], as_dict=True) if doc.course else None -%}
{%- set event = frappe.db.get_value("LMS Event", doc.event_name, ["title", "name", "venue", "start_date"], as_dict=True) if doc.event_name else None -%}
{%- set display_title = (course.title if course else (event.title if event else "")) -%}
{%- set is_event = True if doc.event_name else False -%}
{%- set instructor_parent = doc.event_name if is_event else doc.course -%}
{%- set instructor_parent_type = "LMS Event" if is_event else "LMS Course" -%}
{%- set instructors = frappe.get_all("Course Instructor", filters={"parent": instructor_parent, "parenttype": instructor_parent_type}, pluck="instructor", order_by="idx") if instructor_parent else [] -%}
{%- set approvals = frappe.get_all("CEU Discipline Link", filters={"parent": doc.course, "parenttype": "LMS Course"}, fields=["discipline", "approval_number"]) if doc.course else [] -%}
{%- set base_url = frappe.utils.get_url() -%}

<meta name="pdfkit-orientation" content="Landscape">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;600&family=Inter:wght@300;400;500;700&display=swap" rel="stylesheet">

<div class="cert-page">
    <img class="cert-frame" src="{{ base_url }}/assets/lms/images/cert-frame.png">

    <div class="cert-logos{% if not is_event %} cert-logos-single{% endif %}">
        {% if is_event %}
        <img class="cert-logo-ppt" src="{{ base_url }}/assets/lms/images/ppt-logo.png">
        <img class="cert-logo-ppt4ed" src="{{ base_url }}/assets/lms/images/ppt4ed-logo.png">
        {% else %}
        <img class="cert-logo-ppt4ed-alone" src="{{ base_url }}/assets/lms/images/ppt4ed-logo.png">
        {% endif %}
    </div>

    <div class="cert-title">Certificate of Completion</div>

    <div class="cert-subtitle">PPT4ed In collaboration with Progressive Pediatric Therapy Award this certificate of attendance to:</div>

    <div class="cert-recipient-name">{{ member.full_name if member else doc.member_name }}</div>
    {% if doc.license_info %}<div class="cert-license">{{ doc.license_info }}</div>{% endif %}

    <div class="cert-preamble">for successfully completion of the continuing education course entitled:</div>

    <div class="cert-course-title">{{ display_title }}</div>

    <div class="cert-signatures">
        {% for instructor in instructors %}
        {%- set inst_name = frappe.db.get_value("User", instructor, "full_name") -%}
        {%- set inst_sig = frappe.db.get_value("User", instructor, "signature_image") -%}
        <div class="cert-sig-block">
            {% if inst_sig %}
            <img class="cert-sig" src="{% if inst_sig.startswith('http') %}{{ inst_sig }}{% elif inst_sig.startswith('/') %}{{ base_url }}{{ inst_sig }}{% else %}{{ base_url }}/{{ inst_sig }}{% endif %}">
            {% else %}
            <div class="cert-sig-placeholder"></div>
            {% endif %}
            <div class="cert-sig-line"></div>
            <div class="cert-sig-name">{{ inst_name }}</div>
        </div>
        {% endfor %}
    </div>

    <div class="cert-footer">
        <div class="cert-footer-left">
            {% if doc.ceu_hours %}<div class="cert-footer-heading">Approved: {{ (doc.ceu_hours | int) if (doc.ceu_hours == (doc.ceu_hours | int)) else doc.ceu_hours }} CE Hours for</div>{% endif %}
            {% for a in approvals %}
            <div>{{ a.discipline }} CE Approval #{{ a.approval_number or "PENDING" }}</div>
            {% endfor %}
        </div>
        <div class="cert-footer-right">
            <div>Date: {{ frappe.utils.format_date(doc.issue_date, "medium") }}</div>
            {% if is_event and event.venue %}<div>Location: {{ event.venue }}</div>{% endif %}
        </div>
    </div>
</div>
